                marks[c - r] = grid[r][c]

    # Repeating diagonal motif: the observed sequence is 3, 3, 4, 5
    # with the gaps between the bands retained.
    anchors = sorted(marks)
    if not anchors:
        return [row[:] for row in grid]

    # Find the repeating translation from the motif's extreme marked diagonals.
    period = max(anchors) - min(anchors) + 1
    if period <= 1:
        period = 1

